 private static NBTTagCompound input(int profile){NBTTagCompound tag=new NBTTagCompound();if(profile<=1)return tag;tag.setBoolean("ManualOn",profile%2==1);tag.setBoolean("LightInitialized",true);tag.setInteger("ParticleLevel",profile%4);tag.setIntArray("RedstoneChannels",profile>=3?new int[]{17,19}:new int[]{});tag.setInteger("RedstoneChannel",profile>=3?17:0);tag.setInteger("ChannelLevel",6);tag.setBoolean("ChannelSignal",true);tag.setBoolean("SignalBrightness",profile>=4);tag.setInteger("ParticleThreshold",profile+2);tag.setBoolean("RedstoneInverted",profile%2==1);tag.setBoolean("PropulsionJoin",profile%2==1);tag.setInteger("PropulsionSideTexture",profile*7);if(profile==5){tag.setInteger("ParticleLevel",99);tag.setInteger("ParticleThreshold",99);tag.setString("PropulsionSideTexture","wrong");tag.setIntArray("RedstoneChannels",new int[]{-1});}if(profile>=6){NBTTagCompound forge=new NBTTagCompound(),all=new NBTTagCompound(),main=new NBTTagCompound();main.setIntArray("Channels",new int[]{29,31});main.setInteger("Range",64);main.setBoolean("Local",true);all.setTag("main",main);forge.setTag(com.vandorlabs.redstone.TransmissionSettings.SETTINGS,all);tag.setTag("ForgeData",forge);}return tag;}
